const NOT_FOUND = 'Имена не найдены';

try {
  const sources = (
    $json.data &&
    typeof $json.data === 'object'
  )
    ? $json.data
    : {};

  const allNames = [];

  // Функция пытается достать имя из ФИ / ФИО
  function extractFirstName(fullName) {
    if (typeof fullName !== 'string') {
      return '';
    }

    const cleanStr = fullName
      .replace(/[,;]/g, '')
      .trim();

    if (!cleanStr) {
      return '';
    }

    const words = cleanStr
      .split(/\s+/)
      .filter(Boolean);

    if (words.length === 0) {
      return '';
    }

    // Если всего одно слово
    if (words.length === 1) {
      return words[0];
    }

    // Ищем отчество.
    // Если нашли — имя обычно находится перед ним.
    for (let i = 1; i < words.length; i++) {
      const word = words[i].toLowerCase();

      if (
        word.endsWith('вич') ||
        word.endsWith('вна') ||
        word.endsWith('ична') ||
        word.endsWith('ич')
      ) {
        return words[i - 1];
      }
    }

    // Если отчество не обнаружили,
    // предполагаем формат "Фамилия Имя"
    return words[1] || '';
  }


  // ==========================================
  // 1. Собираем все name из ответа DataTech
  // ==========================================

  for (const source of Object.values(sources)) {

    if (!source || typeof source !== 'object') {
      continue;
    }

    const records = source.data;

    if (!Array.isArray(records)) {
      continue;
    }

    for (const record of records) {

      if (
        !record ||
        typeof record !== 'object' ||
        typeof record.name !== 'string'
      ) {
        continue;
      }

      const rawName = record.name.trim();

      if (!rawName) {
        continue;
      }

      // В одном поле name может быть несколько ФИО через ;
      const splitNames = rawName.split(';');

      for (const value of splitNames) {

        const cleanName = value.trim();

        if (!cleanName) {
          continue;
        }

        // Сохраняем правило исходного Apps Script:
        // записи с латиницей игнорируем
        if (/[a-zA-Z]/.test(cleanName)) {
          continue;
        }

        allNames.push(cleanName);
      }
    }
  }


  // ==========================================
  // 2. Вообще ничего подходящего не найдено
  // ==========================================

  if (allNames.length === 0) {
    return {
      json: {
        client_name: NOT_FOUND
      }
    };
  }


  // ==========================================
  // 3. Группируем варианты по имени человека
  // ==========================================

  const groups = {};

  for (const fullName of allNames) {

    const firstName = extractFirstName(fullName);

    if (!firstName) {
      continue;
    }

    // Чтобы "Иван" и "ИВАН" считались одной группой
    const key = firstName
      .trim()
      .toUpperCase();

    if (!key) {
      continue;
    }

    if (!groups[key]) {
      groups[key] = {
        count: 0,
        longest: fullName
      };
    }

    groups[key].count++;

    // Внутри одной группы предпочитаем
    // наиболее полное ФИО
    if (
      fullName.length >
      groups[key].longest.length
    ) {
      groups[key].longest = fullName;
    }
  }


  // ==========================================
  // 4. Если группы почему-то не сформировались
  // ==========================================

  const groupValues = Object.values(groups);

  if (groupValues.length === 0) {
    return {
      json: {
        client_name: NOT_FOUND
      }
    };
  }


  // ==========================================
  // 5. Выбираем победителя
  // ==========================================

  let winner = null;

  for (const group of groupValues) {

    if (!winner) {
      winner = group;
      continue;
    }

    // Сначала побеждает имя,
    // которое встретилось чаще
    if (group.count > winner.count) {
      winner = group;
      continue;
    }

    // При одинаковой частоте
    // выбираем более полное ФИО
    if (
      group.count === winner.count &&
      group.longest.length > winner.longest.length
    ) {
      winner = group;
    }
  }


  // ==========================================
  // 6. Финальный результат
  // ==========================================

  return {
    json: {
      client_name:
        winner?.longest?.trim() || NOT_FOUND
    }
  };

} catch (error) {

  // Любая неожиданная структура JSON
  // не должна ронять обработку звонка
  return {
    json: {
      client_name: NOT_FOUND
    }
  };
}

// Номер исходной строки Google Sheets.
// В Edit Fields мы ранее сохранили row_number как source_row.
const sourceRow =
  $('Edit Fields').item.json.source_row ?? null;


// Безопасный результат, если LLM вернула некорректный ответ.
const FALLBACK = {
  source_row: sourceRow,
  decision: 'manual_review',
  status: null,
  reason_code: 'INVALID_MODEL_RESPONSE',
  reason_text:
    'Ответ модели не удалось корректно обработать. Требуется ручная проверка.'
};


try {

  // Получаем текст ответа OpenAI
  let rawText =
    $json?.output?.[0]?.content?.[0]?.text;


  // Ответ отсутствует
  if (
    typeof rawText !== 'string' ||
    !rawText.trim()
  ) {
    return {
      json: FALLBACK
    };
  }


  // Убираем случайные ```json ... ```,
  // если модель вдруг их добавит
  rawText = rawText
    .trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/, '')
    .trim();


  // Превращаем строку JSON в объект
  const parsed = JSON.parse(rawText);


  // Разрешённые значения decision
  const allowedDecisions = [
    'auto',
    'manual_review'
  ];


  // Разрешённые статусы
  const allowedStatuses = [
    'лид УМТМ',
    'не лид',
    'стоп-лист',
    null
  ];


  // Проверка decision
  if (
    !allowedDecisions.includes(parsed.decision)
  ) {
    return {
      json: FALLBACK
    };
  }


  // Проверка status
  if (
    !allowedStatuses.includes(parsed.status)
  ) {
    return {
      json: FALLBACK
    };
  }


  // manual_review не должен иметь бизнес-статус
  if (
    parsed.decision === 'manual_review' &&
    parsed.status !== null
  ) {
    return {
      json: FALLBACK
    };
  }


  // auto обязан иметь бизнес-статус
  if (
    parsed.decision === 'auto' &&
    parsed.status === null
  ) {
    return {
      json: FALLBACK
    };
  }


  // Всё корректно
  return {
    json: {
      source_row: sourceRow,

      decision: parsed.decision,
      status: parsed.status,

      reason_code:
        parsed.reason_code ||
        'UNKNOWN_REASON',

      reason_text:
        parsed.reason_text ||
        'Причина моделью не указана.'
    }
  };


} catch (error) {

  // Любая ошибка парсинга →
  // не роняем workflow, отправляем на ручную проверку
  return {
    json: FALLBACK
  };

}

// Текущая обрабатываемая запись
const currentProject =
  String(
    $('If | Validate_Project').item.json.project ?? ''
  ).trim();

const currentDateRaw =
  String(
    $('If | Validate_Project').first().json.call_date ?? ''
  ).trim();

// Парсим даты вида 18.09.26 или 18.09.2026
function parseRuDate(value) {
  if (!value) return null;

  const parts = value.split('.');

  if (parts.length !== 3) return null;

  const day = Number(parts[0]);
  const month = Number(parts[1]);
  let year = Number(parts[2]);

  if (year < 100) {
    year += 2000;
  }

  const date = new Date(year, month - 1, day);

  if (Number.isNaN(date.getTime())) {
    return null;
  }

  return date;
}


// Возвращает предыдущий рабочий день.
// Пока учитываем только субботу и воскресенье.
function previousBusinessDay(date) {
  const result = new Date(date);

  do {
    result.setDate(result.getDate() - 1);
  } while (
    result.getDay() === 0 || // воскресенье
    result.getDay() === 6    // суббота
  );

  return result;
}


function sameDate(a, b) {
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}


const currentDate = parseRuDate(currentDateRaw);

// Fail-safe:
// если текущую дату разобрать нельзя,
// не объявляем запись дублем наугад.
if (!currentDate) {
  return [{
    json: {
      is_duplicate: false,
      duplicate_check_error: true,
      duplicate_reason: 'Не удалось разобрать дату текущего звонка'
    }
  }];
}


const expectedPreviousDate =
  previousBusinessDay(currentDate);

let duplicateFound = false;
let duplicateRow = null;


// $input.all() = все строки с таким телефоном,
// которые вернул Google Sheets
for (const item of $input.all()) {

  const row = item.json;

  const oldProject =
    String(row['Проект'] ?? '').trim();

  const oldDateRaw =
    String(row['Дата'] ?? '').trim();

  // Другой проект нас не интересует
  if (oldProject !== currentProject) {
    continue;
  }

  const oldDate = parseRuDate(oldDateRaw);

  if (!oldDate) {
    continue;
  }

  if (sameDate(oldDate, expectedPreviousDate)) {
    duplicateFound = true;
    duplicateRow = row;
    break;
  }
}


return [{
  json: {
    is_duplicate: duplicateFound,
    duplicate_row: duplicateFound
      ? duplicateRow?.row_number ?? null
      : null
  }
}];

const items = $input.all();

const stats = {
  total: items.length,
  processed: 0,
  manual_review: 0,
  errors: 0,

  lead: 0,
  not_lead: 0,
  stop_list: 0,
  duplicate: 0
};

for (const item of items) {
  const row = item.json ?? {};

  if (row.run_result === 'manual_review') {
    stats.manual_review++;
    continue;
  }

  if (row.run_result === 'error') {
    stats.errors++;
    continue;
  }

  if (row.run_result === 'processed') {
    stats.processed++;

    // Убираем эмодзи и другие символы в начале статуса
    const status = String(row.final_status ?? '')
      .replace(/^[^\p{L}\p{N}]+/u, '')
      .trim();

    switch (status) {
      case 'лид УМТМ':
        stats.lead++;
        break;

      case 'не лид':
        stats.not_lead++;
        break;

      case 'стоп-лист':
        stats.stop_list++;
        break;

      case 'дубль':
        stats.duplicate++;
        break;
    }
  }
}

return [{
  json: {
    run_finished_at: new Date().toISOString(),
    execution_id: $execution.id,
    ...stats
  }
}];
